-- BierKompas: bieren van Belgian Beer Factory (715) en Nederland bier / Mitra (245).
-- Bron: "belgianbeerfactory  bierkompas.xlsx" en "nederland bier bierkompas.xlsx".
-- Uitvoeren via het Supabase-dashboard: SQL Editor -> New query -> plak dit bestand -> Run.
-- Veilig om opnieuw te draaien (bestaande bieren worden bijgewerkt).
-- Id's: 900001+ Belgian Beer Factory, 910001+ Mitra (regelnummer in de Excel),
-- zodat ze nooit botsen met de bierdatabase van de Stichting.

alter table public.beer_catalog add column if not exists image_url text;
alter table public.beer_catalog add column if not exists kleur text;

