on conflict (id) do update set naam = excluded.naam, brouwerij = excluded.brouwerij, stijl = excluded.stijl, verpakking = excluded.verpakking, land = excluded.land, alcohol = excluded.alcohol, gisting = excluded.gisting, kleur = excluded.kleur, bron = excluded.bron, image_url = excluded.image_url;

-- Nederland bier (Mitra)
